impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> From<Rotor<S, T, O>> for Multivector<S, T, O> {
    /// The same multivector as a [`Multivector`], of the same orientation.
    #[inline(always)]
    fn from(x: Rotor<S, T, O>) -> Self {
        Multivector { o: core::marker::PhantomData, c: [x.c[0], <S as gx::Slots>::from_flat(&mut |_| T::zero(), 0), <S as gx::Slots>::from_flat(&mut |_| T::zero(), 0), x.c[1]] }
    }
}

